-- Ids are UUIDv7 generated by the application in Go (uuid.New), never by the
-- database: the column has no default, so a row inserted without an id fails
-- instead of getting a UUID that is not version 7 (PostgreSQL < 18 has no
-- uuidv7(), and gen_random_uuid() is version 4).
CREATE TABLE tasks (
    id         uuid        PRIMARY KEY,
    title      text        NOT NULL CONSTRAINT tasks_title_length CHECK (char_length(title) BETWEEN 1 AND 200),
    done       boolean     NOT NULL DEFAULT false,
    version    integer     NOT NULL DEFAULT 1 CONSTRAINT tasks_version_positive CHECK (version >= 1),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
